package com.bank.tiered;

import java.time.Duration;
import java.util.logging.*;

public class TieredStorageDemo {
    private static final Logger log = Logger.getLogger(TieredStorageDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Keep 1 day locally, 7 years total (rest in remote object storage).
        TieredRetentionPlanner planner = new TieredRetentionPlanner(
            Duration.ofDays(1), Duration.ofDays(2555));

        // Where is each read served from?
        logTier(planner, "Rajesh recent swipe", Duration.ofHours(2));
        logTier(planner, "Priya last-week rent credit", Duration.ofDays(5));
        logTier(planner, "Auditor request (3 years ago)", Duration.ofDays(1095));
        logTier(planner, "Beyond retention (8 years ago)", Duration.ofDays(2920));

        // Cost benefit: local footprint vs remote footprint over the retention window.
        long dailyBytes = 500L * 1024 * 1024 * 1024;   // 500 GB/day of transaction data
        long localGb = planner.localFootprintBytes(dailyBytes) / (1024 * 1024 * 1024);
        long remoteGb = planner.remoteFootprintBytes(dailyBytes) / (1024 * 1024 * 1024);
        log.info(() -> "Local disk needed: " + localGb + " GB (hot) vs remote: "
                + remoteGb + " GB (cold, cheap)");
    }

    private static void logTier(TieredRetentionPlanner planner, String label, Duration age) {
        String tier = planner.tierFor(age);
        log.info(() -> label + " (age " + age.toDays() + "d) → " + tier);
    }
}

