class TieredRetentionPlanner {
    private final Duration localRetention;
    private final Duration totalRetention;
    TieredRetentionPlanner(Duration localRetention, Duration totalRetention) {
        if (localRetention.compareTo(totalRetention) > 0)
            throw new IllegalArgumentException("local retention cannot exceed total retention");
        this.localRetention = localRetention;
        this.totalRetention = totalRetention;
    }

    // Decide which tier serves a read of the given age.
    String tierFor(Duration age) {
        if (age.compareTo(localRetention) <= 0) return "LOCAL DISK (fast, hot)";
        if (age.compareTo(totalRetention) <= 0) return "REMOTE STORAGE (S3, cold, cheap)";
        return "EXPIRED (beyond total retention, deleted)";
    }

    long localFootprintBytes(long dailyBytes) {
        return dailyBytes * localRetention.toDays();
    }

    long remoteFootprintBytes(long dailyBytes) {
        long remoteDays = totalRetention.toDays() - localRetention.toDays();
        return dailyBytes * remoteDays;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
